    rr0=max(0,r0-pad); rr1=min(H-1,r1+pad); cc0=max(0,c0-pad); cc1=min(W-1,c1+pad)
    out=np.full((H,W),int(frame))
    # recolor interior of object bbox (strictly inside its own frame) with ic
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            if m[r,c]==frame:
                out[r,c]=ic
    return out.tolist()
