    for x in range(H):
        for y in range(W):
            if a[x,y]==color and not seen[x,y]:
                st=[(x,y)]; seen[x,y]=True; comp=[]
                while st:
                    p,q=st.pop(); comp.append((p,q))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        px,py=p+dx,q+dy
                        if 0<=px<H and 0<=py<W and a[px,py]==color and not seen[px,py]:
                            seen[px,py]=True; st.append((px,py))
                out.append(comp)
    return out
